import {narratives,coins,stages,stageDescriptions,buildView,ageLabel,narrativeInWindow,coinContext,crossoverEvents} from './narrative-data.mjs';
import {contractForCopy,copyContract} from './contract-copy.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(n);
const signed=n=>`${n>0?'+':''}${n}%`, num=n=>n.toLocaleString('en-US');
const state={hours:4,group:'all',stage:'all',query:''};
let storageAvailable=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageAvailable=false;return false}}
const savedSources=read('meme-fast-radar-sources-v1',[]);
let sources=Array.isArray(savedSources)?savedSources.filter(s=>s&&typeof s.handle==='string'&&/^@[A-Za-z0-9_]{1,15}$/.test(s.handle)&&typeof s.category==='string'&&typeof s.group==='string'&&Number.isInteger(s.weight)&&s.weight>=1&&s.weight<=5):[];
const previous=read('meme-fast-radar-visit-v1',null);
const currentSnapshot=buildView().trends.map(n=>({id:n.id,rank:n.rank,sources:n.sources}));
save('meme-fast-radar-visit-v1',{at:new Date().toISOString(),rows:currentSnapshot});
function metrics(items){return `<dl class="signal-metrics">${items.map(([label,value,cls=''])=>`<div><dt>${label}</dt><dd class="${cls}">${value}</dd></div>`).join('')}</dl>`}
function stageTag(n){return n.stage===null?'<span class="stage-tag">LC unclassified</span>':`<span class="stage-tag ${n.stage>=5?'late':''}">LC${n.stage} · ${stages[n.stage]}</span>`}
const originLabel=origin=>origin==='narrative_first'?'Narrative → Coin':origin==='coin_first'?'Coin → Narrative':'Origin not established';
function caButton(c){
 const address=contractForCopy(c);
 return `<button type="button" class="ca-copy" data-copy-ca="${esc(c.id)}" ${address?'':'disabled'} aria-label="${address?'Copy':'Unavailable'} ${esc(c.symbol)} contract address on ${esc(c.chain)}" title="${address?esc(c.chain+' · '+address):'No verified contract address for this example token'}"><span>CA</span><span aria-hidden="true">⧉</span>${address?'':'<span class="ca-unavailable">—</span>'}</button>`;
}
function tokenTags(n){
 const matched=coins.filter(c=>c.narrative===n.id);
 return matched.length?matched.map(c=>`<span class="token-match"><span class="token-tag">$${esc(c.symbol)} matched</span>${caButton(c)}</span>`).join(''):'<span class="token-tag no-token">No token detected</span>';
}
let expandedTrends=false,expandedCoins=false;
let copyStatusTimer;
function empty(title,body){return `<div class="empty-state"><strong>${title}</strong>${body}<button type="button" data-reset>Reset filters</button></div>`}
function render(){
 const view=buildView(state);
 $('#trend-count').textContent=view.trends.length;$('#coin-count').textContent=view.coins.length;$('#crossover-count').textContent=view.crossovers.length;
 $('#filter-status').textContent=`${view.trends.length} narrative${view.trends.length===1?'':'s'} · ${view.coins.length} coin${view.coins.length===1?'':'s'} · ${state.hours===72?'3-day':state.hours+'-hour'} social window${state.group!=='all'?' · '+state.group:''}${state.stage!=='all'?' · '+({early:'LC0–2',conversion:'LC3–4',late:'LC5–6',unclassified:'Unclassified'}[state.stage]):''} · fixed example snapshot`;
 $('#trends').innerHTML=view.trends.slice(0,expandedTrends?20:3).map(n=>`<article class="signal-card"><div class="signal-top"><span class="rank">${String(n.rank).padStart(2,'0')}</span><div class="signal-name"><h3>${n.title}</h3></div><span class="direction ${n.direction}">${n.direction==='rising'?'↗ Rising':n.direction==='fading'?'↘ Fading':'→ Watching'}</span></div><div class="tags">${stageTag(n)}${tokenTags(n)}</div><p class="signal-summary">${n.summary}</p>${metrics([['Independent sources',num(n.sources)],['Mentions',num(n.mentions)],['Velocity / hour',signed(n.velocity),n.velocity>0?'positive':n.velocity<0?'negative':'']])}<div class="signal-bottom"><span>First ${ageLabel(n.first)} ago · active ${ageLabel(n.latest)} ago</span><div class="signal-actions"><button class="text-button" data-evidence="${n.id}">Evidence ↗</button><button class="text-button" data-timeline="${n.id}">Timeline</button></div></div></article>`).join('')||empty('No narratives in this view.','Market activity can exist before a narrative forms.');
 $('#coins').innerHTML=view.coins.slice(0,expandedCoins?20:3).map(c=>{
  const context=coinContext(c,state.hours),n=context.narrative;
  return `<article class="signal-card"><div class="signal-top"><span class="rank">${String(c.rank).padStart(2,'0')}</span><div class="signal-name"><h3>$${c.symbol}</h3><small>${c.name} · ${c.chain} · ${ageLabel(c.age)} old</small></div><span class="direction ${c.growth<0?'fading':''}">${signed(c.growth)} holders/h</span></div><div class="tags">${stageTag(context)}${caButton(c)}<span class="origin-tag">${originLabel(context.origin)}</span></div>${metrics([['Market cap',money(c.mc)],['24h volume',money(c.volume)],['24h unique buyers',num(c.buyers)]])}<div class="coin-context">${n?`<strong>${context.sources} social sources</strong> · ${c.strength.toLowerCase()} narrative<br>${n.title}`:'<strong>No narrative matched</strong> · Social coverage unknown'}</div><div class="signal-bottom"><span>Liquidity ${money(c.liquidity)}</span><div class="signal-actions"><button class="text-button" data-coin="${esc(c.id)}">Coin details ↗</button>${n?`<button class="text-button" data-evidence="${n.id}">Narrative</button>`:''}</div></div></article>`;
 }).join('')||empty('No coins in this view.','A narrative can be meaningful before a token exists.');
 for(const [id,total,expanded,label] of [['trends-more',view.trends.length,expandedTrends,'narratives'],['coins-more',view.coins.length,expandedCoins,'coins']]){
  const button=$('#'+id);button.hidden=total<=3;button.textContent=expanded?'Show top 3':`View all ${total} ${label}`;button.setAttribute('aria-expanded',expanded);
 }
 $('#crossovers').innerHTML=view.crossovers.map(c=>`<button type="button" class="crossover-card ${c.type==='coin_to_trend'?'coin-first':''}" data-crossover="${c.narrative}"><span class="crossover-direction">${c.type==='trend_to_coin'?'TREND → COIN':'COIN → TREND'} · ${ageLabel(c.age)} AGO</span><strong>${c.title} <span aria-hidden="true">↗</span></strong><span class="crossover-brief">${c.type==='trend_to_coin'?ageLabel(c.lead)+' narrative lead · '+c.competing+' competing tokens':c.outside+' outside accounts · '+ageLabel(c.lead)+' launch lead'}</span></button>`).join('')||'<p class="crossover-empty">No crossovers in this window. Try a wider window or different filters.</p>';
}
function openDetail(title,body){$('#detail-title').textContent=title;$('#detail-body').innerHTML=body;$('#detail-dialog').showModal()}
function timeline(n){return `<ol class="timeline-list">${n.timeline.map(([time,event])=>`<li><time>${time}</time>${event}</li>`).join('')}</ol>`}
function showNarrative(id,onlyTimeline=false){const n=narrativeInWindow(id,state.hours);if(!n)return;openDetail(n.title,`<div class="tags">${stageTag(n)}${tokenTags(n)}</div><p class="detail-summary">${n.summary}</p><p class="detail-note">Fictional example · ${state.hours}H social window · times relative to the sample snapshot.</p>${onlyTimeline?timeline(n):`${metrics([['Sources in window',num(n.sources)],['Mentions in window',num(n.mentions)],['Velocity / hour',signed(n.velocity)]])}<section class="detail-section"><h3>Representative evidence</h3><p class="detail-note">Illustrative posts and handles, not retrieved X posts. These show the narrative’s history and may predate your selected window.</p>${n.evidence.map((p,i)=>`<article class="evidence-post"><div><span>@${n.keys[i%n.keys.length]}</span><span>Example source ${i+1}</span></div><p>${p}</p></article>`).join('')}</section><section class="detail-section"><h3>Narrative timeline</h3>${timeline(n)}</section>`}${!n.coin?'<p class="no-token-note">No token is matched. This topic stays in Top Trending on its own merits.</p>':''}`)}
function showCoin(id){
 const c=coins.find(c=>c.id===id);if(!c)return;
 const context=coinContext(c,state.hours),n=context.narrative,address=contractForCopy(c);
 openDetail('$'+c.symbol+' · '+c.name,`<p class="detail-summary">${c.chain} · ${ageLabel(c.age)} old · ${originLabel(context.origin)}</p><div class="contract-detail">${caButton(c)}${address?`<code>${esc(address)}</code>`:'<span class="detail-note">Fictional token · no verified contract address.</span>'}</div>${metrics([['Market cap',money(c.mc)],['Liquidity',money(c.liquidity)],['24h volume',money(c.volume)]])}${metrics([['24h unique buyers',num(c.buyers)],['Holders',num(c.holders)],['Holder growth / h',signed(c.growth)]])}${metrics([['24h buys',num(c.buyCount)],['24h sells',num(c.sellCount)],['Narrative strength',c.strength]])}<section class="detail-section">${n?`<h3>${n.title}</h3><p class="detail-note">${n.sources} sources · ${n.mentions} mentions in the ${state.hours}H social window</p><p class="detail-summary">${n.summary}</p>${timeline(n)}`:'<h3>No narrative matched</h3><p class="detail-summary">Buyer activity puts this example coin in Top Coins. Its origin, social participation, and lifecycle are not established yet.</p>'}</section>`);
}
async function handleCopy(button){
 const coin=coins.find(c=>c.id===button.dataset.copyCa),result=await copyContract(coin,navigator.clipboard);
 if(result.status==='copied'){
  button.innerHTML='<span>Copied</span><span aria-hidden="true">✓</span>';
  $('#copy-status').textContent=`${coin.symbol} contract address copied on ${coin.chain}.`;
  clearTimeout(copyStatusTimer);copyStatusTimer=setTimeout(()=>{$('#copy-status').textContent=''},3500);
  setTimeout(()=>{if(button.isConnected)button.innerHTML='<span>CA</span><span aria-hidden="true">⧉</span>'},1800);
 }else if(result.status==='manual'){
  $('#copy-address').value=result.address;$('#copy-note').textContent=`Clipboard access is unavailable. Copy the ${coin.symbol} address on ${coin.chain} below.`;
  $('#copy-dialog').showModal();$('#copy-address').focus();$('#copy-address').select();
 }else $('#copy-status').textContent='No verified contract address is available.';
}
function showChanges(){const valid=previous&&Array.isArray(previous.rows)&&Number.isFinite(Date.parse(previous.at));let body;if(valid){const changes=currentSnapshot.flatMap(n=>{const before=previous.rows.find(r=>r.id===n.id);const title=narratives.find(r=>r.id===n.id).title;if(!before)return [`${title} entered the example ranking at #${n.rank}.`];const lines=[];if(n.rank!==before.rank)lines.push(`${title}: #${before.rank} → #${n.rank}.`);if(n.sources!==before.sources)lines.push(`${title}: ${n.sources-before.sources>0?'+':''}${n.sources-before.sources} independent sources.`);return lines});body=`<p class="detail-summary">Compared with your last visit on ${esc(new Date(previous.at).toLocaleString())}.</p>${changes.length?`<ul class="changes-list">${changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:'<p class="empty-state"><strong>No changes to the example snapshot.</strong>This preview uses fixed data; refreshing does not invent new activity.</p>'}`}else{body='<p class="detail-summary">Your first example snapshot has been saved for the next visit.</p><p class="detail-note">Here is an illustrative comparison with an earlier example snapshot, using the unfiltered 4H ranking:</p><ul class="changes-list">'+currentSnapshot.map(n=>{const source=narratives.find(r=>r.id===n.id);return source.previousRank===n.rank?'':`<li>${source.title}: ${source.previousRank?'#'+source.previousRank+' → #'+n.rank:'new at #'+n.rank}.</li>`}).join('')+'</ul>'}openDetail('What changed',body+'<p class="detail-note">Comparison uses all groups and stages in the 4H social window. '+(storageAvailable?'Saved only on this browser.':'Browser storage is unavailable; this visit cannot be saved.')+'</p>')}
function renderSources(){ $('#source-list').innerHTML=sources.length?sources.map(s=>`<div class="source-row"><div><strong>${esc(s.handle)}</strong><small>${esc(s.category)} · ${esc(s.group)} · weight ${s.weight}/5</small></div><button data-remove-source="${esc(s.handle)}" aria-label="Remove ${esc(s.handle)}">Remove</button></div>`).join(''):'<p class="empty-state">No sources saved yet. Add an account above to start your watchlist.</p>'; }
function reset(){Object.assign(state,{hours:4,group:'all',stage:'all',query:''});$('#group').value='all';$('#radar-search').value='';document.querySelectorAll('[data-hours]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.hours)===4));document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.stage==='all'));render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.hours){state.hours=Number(b.dataset.hours);document.querySelectorAll('[data-hours]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}if(b.dataset.stage){state.stage=b.dataset.stage;document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()}if(b.dataset.evidence)showNarrative(b.dataset.evidence);if(b.dataset.timeline)showNarrative(b.dataset.timeline,true);if(b.dataset.coin)showCoin(b.dataset.coin);if(b.hasAttribute('data-reset'))reset();if(b.dataset.removeSource){sources=sources.filter(s=>s.handle!==b.dataset.removeSource);const saved=save('meme-fast-radar-sources-v1',sources);renderSources();$('#source-status').textContent=saved?'Account removed.':'Removed for this session; browser storage is unavailable.'}});
$('#group').addEventListener('change',e=>{state.group=e.target.value;render()});$('#radar-search').addEventListener('input',e=>{state.query=e.target.value;render()});
$('#trends-more').onclick=()=>{expandedTrends=!expandedTrends;render()};
$('#coins-more').onclick=()=>{expandedCoins=!expandedCoins;render()};
document.addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.copyCa)handleCopy(button);
 if(button.dataset.crossover){
  const event=crossoverEvents.find(c=>c.narrative===button.dataset.crossover),n=narratives.find(n=>n.id===event.narrative);
  openDetail(event.title,`<p class="detail-summary">${event.description}</p><p class="detail-note">Fictional example · ${ageLabel(event.age)} ago.</p><div class="tags">${tokenTags(n)}</div><div class="crossover-facts"><span><strong>${ageLabel(event.lead)}</strong>${event.type==='trend_to_coin'?'narrative lead time':'launch before social'}</span><span><strong>${event.competing??event.outside}</strong>${event.competing?'competing example tokens':'outside accounts'}</span></div>${timeline(n)}`);
 }
});
$('#lifecycle-open').onclick=()=>openDetail('Lifecycle · LC0 to LC6',`<p class="dialog-intro">A path from raw attention to crowd participation. Stages can reverse, and many trends never become tokens.</p><div class="lifecycle-list">${stages.map((s,i)=>`<div class="lifecycle-row"><strong>LC${i}</strong><div><h3>${s}</h3><p>${stageDescriptions[i]}</p></div></div>`).join('')}</div><p class="no-token-note">LC2 can remain a cultural meme and fade without entering LC3. Coin-first narratives can enter the cycle after a token already exists.</p>`);
$('#changes-open').onclick=showChanges;$('#sources-open').onclick=()=>{renderSources();$('#sources-dialog').showModal()};
$('#source-form').addEventListener('submit',e=>{e.preventDefault();const handle='@'+$('#source-handle').value.replace(/^@/,'');if(sources.some(s=>s.handle.toLowerCase()===handle.toLowerCase())){$('#source-status').textContent='That account is already in your watchlist.';return}sources.push({handle,category:$('#source-category').value,group:$('#source-group').value,weight:Number($('#source-weight').value)});const saved=save('meme-fast-radar-sources-v1',sources);$('#source-status').textContent=saved?'Account saved on this browser. Collection is not connected.':'Added for this session; browser storage is unavailable.';$('#source-handle').value='';renderSources();$('#source-handle').focus()});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
render();
